#!/usr/bin/env python3
"""Embeds Resources/logos/*.svg (agent and tool logos from svgl.app) in
Sources/TermyNext/ProgramLogoData.swift, so the app needs no resource bundle.
Run it after adding or replacing a logo."""
import base64
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
logos = sorted((root / "Resources" / "logos").glob("*.svg"))
lines = [
    "// Generated by scripts/gen-logos.py from Resources/logos. Do not edit.",
    "// Logos from svgl.app; they are trademarks of their owners.",
    "",
    "enum ProgramLogoData {",
    "    /// SVG files as base64, by file name without extension.",
    "    static let svgs: [String: String] = [",
]
for logo in logos:
    data = base64.b64encode(logo.read_bytes()).decode()
    lines.append(f'        "{logo.stem}": "{data}",')
lines += ["    ]", "}", ""]
(root / "Sources" / "TermyNext" / "ProgramLogoData.swift").write_text("\n".join(lines))
print(f"embedded {len(logos)} logos")
